{"path": "features/schemes/finder.py", "content": """"Live government scheme finder.

This module is intentionally self-contained under ``features/schemes`` so the
feature can be imported by the Flask app later without changing existing code.
It validates a short user bio, calls the live government schemes API, and
returns human-readable eligibility explanations.
"""

from __future__ import annotations

from dataclasses import dataclass
import json
import re
from typing import Any
from urllib.parse import urlencode
from urllib.request import urlopen

API_URL = "https://api.myscheme.gov.in/search/v5/schemes"
DEFAULT_QUERY = "housing"
MAX_BIO_LENGTH = 1000


class BioValidationError(ValueError):
    """Raised when a user's bio is missing or cannot be interpreted safely."""


@dataclass(frozen=True)
class Bio:
    """Validated facts extracted from a user's free-form bio."""

    text: str
    income: int


@dataclass(frozen=True)
class EligibilityExplanation:
    """Eligibility result for a single scheme."""

    name: str
    eligible: bool
    reason: str


_INCOME_PATTERNS = (
    re.compile(r"(?:income|earn(?:ing)?s?|salary|wage)\D{0,20}(\d[\d,]*)", re.I),
    re.compile(r"(?:₹|rs\.?|inr)\s*(\d[\d,]*)", re.I),
    re.compile(r"\b(\d[\d,]*)\s*(?:income|salary|wage|per\s+(?:year|annum|month))", re.I),
)


_TEXT_HAS_LETTER = re.compile(r"[A-Za-z]")


def parse_bio(bio: str) -> Bio:
    """Validate and extract required facts from a user's bio.

    The current live API data exposes income thresholds, so the bio must include
    an income-like amount. The function rejects empty, non-textual, overly long,
    negative, or suspiciously ambiguous input before any API matching happens.
    """

    if not isinstance(bio, str):
        raise BioValidationError("Bio must be text.")

    text = bio.strip()
    if not text:
        raise BioValidationError("Bio is required.")
    if len(text) > MAX_BIO_LENGTH:
        raise BioValidationError("Bio is too long; keep it under 1000 characters.")
    if not _TEXT_HAS_LETTER.search(text):
        raise BioValidationError("Bio must include a short description, not just numbers.")
    if re.search(r"(?:income|earn(?:ing)?s?|salary|wage)\D{0,20}-\s*\d", text, re.I):
        raise BioValidationError("Income cannot be negative.")

    income = _extract_income(text)
    if income is None:
        raise BioValidationError("Bio must include income, salary, or earnings information.")

    return Bio(text=text, income=income)


def _extract_income(text: str) -> int | None:
    for pattern in _INCOME_PATTERNS:
        match = pattern.search(text)
        if match:
            return int(match.group(1).replace(",", ""))
    return None


def fetch_live_schemes(query: str = DEFAULT_QUERY, *, timeout: float = 5.0) -> list[dict[str, Any]]:
    """Fetch schemes from the live government schemes API."""

    params = urlencode({"lang": "en", "q": query})
    with urlopen(f"{API_URL}?{params}", timeout=timeout) as response:  # noqa: S310 - fixed HTTPS API URL
        payload = json.loads(response.read().decode("utf-8"))

    schemes = payload.get("schemes")
    if not isinstance(schemes, list):
        raise ValueError("Unexpected schemes API response: missing schemes list.")
    return schemes


def find_eligible_schemes(
    bio: str,
    *,
    query: str = DEFAULT_QUERY,
    schemes: list[dict[str, Any]] | None = None,
) -> list[EligibilityExplanation]:
    """Return eligibility explanations for schemes matching the user's bio.

    ``schemes`` is injectable for tests; when omitted, the live API is called.
    """

    parsed = parse_bio(bio)
    live_schemes = schemes if schemes is not None else fetch_live_schemes(query)

    explanations: list[EligibilityExplanation] = []
    for scheme in live_schemes:
        name = str(scheme.get("name", "Unnamed scheme"))
        min_income = _optional_int(scheme.get("min_income"))

        if min_income is None:
            explanations.append(
                EligibilityExplanation(
                    name=name,
                    eligible=False,
                    reason="Cannot determine eligibility because the scheme has no income threshold in the live API response.",
                )
            )
            continue

        eligible = parsed.income >= min_income
        comparator = "meets" if eligible else "does not meet"
        explanations.append(
            EligibilityExplanation(
                name=name,
                eligible=eligible,
                reason=(
                    f"Your stated income of {parsed.income} {comparator} "
                    f"the scheme's minimum income requirement of {min_income}."
                ),
            )
        )

    return explanations


def _optional_int(value: Any) -> int | None:
    if value is None or isinstance(value, bool):
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        return None
